--
-- TOC entry 315 (class 1259 OID 62817)
-- Name: vw_Rastreamento_Completo; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public."vw_Rastreamento_Completo" AS
 SELECT r."IDRASTREAMENTO",
    r."IDVIAGEM",
    r."CDCADASTRO",
    m."RZSOCIAL" AS "NMMOTORISTA",
    r."LATITUDE",
    r."LONGITUDE",
    r."ALTITUDE",
    r."VELOCIDADE",
        CASE r."FGSTATUS"
            WHEN 'P'::bpchar THEN 'Parado'::text
            WHEN 'M'::bpchar THEN 'Em Movimento'::text
            ELSE 'Desconhecido'::text
        END AS "STATUS",
    r."DIRECAO",
        CASE
            WHEN ((r."DIRECAO" >= (0)::numeric) AND (r."DIRECAO" <= 22.5)) THEN 'Norte'::text
            WHEN ((r."DIRECAO" >= 22.5) AND (r."DIRECAO" <= 67.5)) THEN 'Nordeste'::text
            WHEN ((r."DIRECAO" >= 67.5) AND (r."DIRECAO" <= 112.5)) THEN 'Leste'::text
            WHEN ((r."DIRECAO" >= 112.5) AND (r."DIRECAO" <= 157.5)) THEN 'Sudeste'::text
            WHEN ((r."DIRECAO" >= 157.5) AND (r."DIRECAO" <= 202.5)) THEN 'Sul'::text
            WHEN ((r."DIRECAO" >= 202.5) AND (r."DIRECAO" <= 247.5)) THEN 'Sudoeste'::text
            WHEN ((r."DIRECAO" >= 247.5) AND (r."DIRECAO" <= 292.5)) THEN 'Oeste'::text
            WHEN ((r."DIRECAO" >= 292.5) AND (r."DIRECAO" <= 337.5)) THEN 'Noroeste'::text
            WHEN ((r."DIRECAO" >= 337.5) AND (r."DIRECAO" <= (360)::numeric)) THEN 'Norte'::text
            ELSE NULL::text
        END AS "DIRECAO_CARDINAL",
    r."PRECISAO",
    r."BATERIA",
    r."DHREGISTRO",
        CASE r."TIPO"
            WHEN 'A'::bpchar THEN 'Automático'::text
            WHEN 'M'::bpchar THEN 'Manual'::text
            ELSE 'Desconhecido'::text
        END AS "TIPO_ENVIO",
    r."FONTE",
    r."VERSAOAPP"
   FROM (public."VIAGEMRASTREAMENTO" r
     LEFT JOIN public."CADASTROGERAL" m ON ((r."CDCADASTRO" = m."CDCADASTRO")));


ALTER VIEW public."vw_Rastreamento_Completo" OWNER TO postgres;

